{% dnd_area "kb-article"
  label="Article",
  class="article-wrapper"
%}
  {% dnd_section
      padding={
        "top": 0,
        "left": 0,
        "bottom": 0,
        "right": 0
      }
  %}
    {% dnd_column %}
      {% dnd_row %}
        {% dnd_module "article-date" path="@hubspot/kb_article_date" %}
        {% end_dnd_module %}
      {% end_dnd_row %}
      {% dnd_row %}
        {% dnd_module "article-title" path="@hubspot/kb_article_title" %}
        {% end_dnd_module %}
      {% end_dnd_row %}
      {% dnd_row %}
        {% dnd_module "article-subtitle" path="@hubspot/kb_article_subtitle" %}
        {% end_dnd_module %}
      {% end_dnd_row %}
      {% dnd_row %}
        {% dnd_module "article-body" path="@hubspot/kb_article_body" %}
        {% end_dnd_module %}
      {% end_dnd_row %}
    {% end_dnd_column %}
  {% end_dnd_section %}
{% end_dnd_area %}
